import { useState } from "react";

const validate = (v) => {
  const e = {};
  if (!v.email.includes("@")) e.email = "Email không hợp lệ";
  if (v.password.length < 8) e.password = "Mật khẩu tối thiểu 8 ký tự";
  return e;
};

export default function App() {
  const [values, setValues] = useState({ email: "", password: "" });
  const [touched, setTouched] = useState({});
  const [done, setDone] = useState(false);
  const errors = validate(values);                 // DẪN XUẤT từ state, không lưu riêng
  const valid = Object.keys(errors).length === 0;

  const bind = (name) => ({
    value: values[name],
    onChange: (e) => setValues({ ...values, [name]: e.target.value }),
    onBlur: () => setTouched({ ...touched, [name]: true }),
  });

  return (
    <form onSubmit={(e) => { e.preventDefault(); if (valid) setDone(true); }}>
      <input id="email" placeholder="Email" {...bind("email")} />
      {touched.email && errors.email && <p id="email-err">{errors.email}</p>}
      <input id="pw" type="password" placeholder="Mật khẩu" {...bind("password")} />
      {touched.password && errors.password && <p id="pw-err">{errors.password}</p>}
      <button id="go" disabled={!valid}>Đăng ký</button>
      {done && <p id="ok">Đã gửi!</p>}
    </form>
  );
}

